import React, { useState, useRef, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { useParams } from 'react-router-dom';
import { downloadMedia } from 'helpers';

import VideoPlayer from 'react-player';
import { Modal, Menu, Dropdown, Carousel, Tag } from 'antd';
import {
  DownOutlined,
  UpOutlined,
  RightOutlined,
  LeftOutlined,
} from '@ant-design/icons';
import CommentBox from '../CommentBox';
import AttachmentFileCard from '../AttachmentFileCard';
import BrandUploadDocumentModal from '../BrandUploadDocumentModal';
import download from 'assets/images/download.svg';
import paperclip from 'assets/images/paperclip.svg';
import demoImg from 'assets/images/project1.jpg';
import { creativeUpdateStatusAction } from 'redux/brands/creatives/actions';

import './styles.scss';

const CreativeModal = ({
  src,
  className,
  versionTrue,
  influencerStatus,
  emptystateInfluncer,
  creative,
  setPage,
  influncerName,
}) => {
  const dispatch = useDispatch();
  let { id } = useParams();
  const [visible, setVisible] = useState(false);
  const [showFiles, setShowFiles] = useState(false);
  const [playing, setPlaying] = useState(false);
  const [creativeStatus, setCreativeStatus] = useState('');
  const poster = 'http://www.example.com/path/to/video_poster.jpg';
  const slider = useRef(null);

  useEffect(() => {
    setCreativeStatus(creative.status);
  }, []);

  const menu = (status) => {
    return (
      <Menu>
        <Menu.Item key='accepted'>
          <div className='flex flex-column'>
            <label className='flex justify-between items-center mb-10 cursor-pointer'>
              <span>Approved</span>
              <input
                type='radio'
                name='status'
                value='accepted'
                onChange={(e) => handleMenuClick(e.target.value)}
                checked={status === 'accepted'}
                className='cursor-pointer'
              />
            </label>
          </div>
        </Menu.Item>
        <Menu.Item key='rejected'>
          <div className='flex flex-column'>
            <label className='flex justify-between items-center mb-10 cursor-pointer'>
              <span>Rejected</span>
              <input
                type='radio'
                name='status'
                value='rejected'
                checked={status === 'rejected'}
                onChange={(e) => handleMenuClick(e.target.value)}
                className='cursor-pointer'
              />
            </label>
          </div>
        </Menu.Item>
        <Menu.Item key='pending'>
          <div className='flex flex-column'>
            <label className='flex justify-between items-center mb-10 cursor-pointer'>
              <span>Pending</span>
              <input
                type='radio'
                name='status'
                value='pending'
                checked={status === 'pending'}
                onChange={(e) => handleMenuClick(e.target.value)}
                className='cursor-pointer'
              />
            </label>
          </div>
        </Menu.Item>
      </Menu>
    );
  };

  const handleMenuClick = (value) => {
    setCreativeStatus(value);
    dispatch(
      creativeUpdateStatusAction({
        status: value,
        projectId: id,
        creativeId: creative.id,
      })
    );
  };

  function onChange(a, b, c) {
    console.log(a, b, c);
  }

  const showAttachFiles = () => {
    setShowFiles(!showFiles);
  };

  const closeModal = (val) => {
    setPlaying(false);
    setShowFiles(false);

    setTimeout(() => {
      setVisible(val);
    }, 500);
  };

  const pauseVideo = () => {
    setPlaying(false);
  };

  const playVideo = () => {
    setPlaying(true);
  };

  return (
    <>
      {versionTrue ? (
        <div className='version-text' onClick={() => setVisible(true)}>
          <img src={demoImg} width='80' height='80' className='version-img' />
          <span>
            <span className={className}>4 versions</span>
            <RightOutlined className='ml-4' />
          </span>
        </div>
      ) : (
        <img
          alt=''
          onClick={() => {
            setVisible(true);
          }}
          src={src}
          className={`cursor-pointer ${className}`}
        />
      )}
      <Modal
        // title='Basic Modal'
        visible={visible}
        onOk={() => setVisible(false)}
        onCancel={() => closeModal(false)}
        width={1100}
        style={{ top: 40 }}
        className='custom-modal'
      >
        <div className='creative-modal'>
          <div className='creative-modal-header flex justify-between'>
            <p className='title'>{influncerName}</p>
            <div className=''>
              {influencerStatus ? (
                <div>
                  <span>Status: </span>
                  <button className='bg-green-outline'>Approved</button>
                </div>
              ) : (
                <Dropdown overlay={menu(creativeStatus)} trigger={['click']}>
                  <a
                    className='ant-dropdown-link'
                    onClick={(e) => e.preventDefault()}
                  >
                    Select a status <DownOutlined />
                  </a>
                </Dropdown>
              )}
            </div>
          </div>
          <div className='creative-modal-body'>
            <div className='flex mobile-section'>
              <div className='carousal-section'>
                <LeftOutlined
                  onClick={() => slider.current.prev()}
                  className='slider-left-icon'
                />
                <Carousel afterChange={onChange} ref={slider}>
                  {creative.media.map((media) => {
                    return (
                      <div className='slider-box'>
                        <Tag color='cyan'>{media.versionTag}</Tag>
                        {media.mimeType.includes('image') ? (
                          <img
                            src={`${process.env.REACT_APP_IMAGE_BASE_URL}/${media.slug}`}
                            className='contentStyle'
                          />
                        ) : (
                          <VideoPlayer
                            url={`${process.env.REACT_APP_VIDEO_BASE_URL}/${media.slug}`}
                            poster={poster}
                            className='video-contentStyle'
                            onPause={pauseVideo}
                            onPlay={playVideo}
                            playing={playing}
                            controls={true}
                          />
                        )}
                        <img
                          src={download}
                          alt='download icon'
                          className='icons-custom cursor-pointer'
                          onClick={() => downloadMedia(media.slug)}
                        />
                      </div>
                    );
                  })}
                  {/* <div className='slider-box'>
                    <Tag color='cyan'>Version 2</Tag>

                    <VideoPlayer
                      url='https://youtu.be/qgdfBnOQAkg'
                      poster={poster}
                      className='video-contentStyle'
                      onPause={pauseVideo}
                      onPlay={playVideo}
                      playing={playing}
                      controls={true}
                    />

                    <img
                      src={download}
                      alt=''
                      className='icons-custom cursor-pointer'
                    />
                  </div>
                  <div className='slider-box'>
                    <Tag color='cyan'>Version 3</Tag>
                    <img src={infImg} className='contentStyle' />
                    <img
                      src={download}
                      alt=''
                      className='icons-custom cursor-pointer'
                    />
                  </div> */}
                </Carousel>
                <RightOutlined
                  onClick={() => slider.current.next()}
                  className='slider-right-icon'
                />
              </div>
              <div className='comment-section'>
                <div className='flex justify-between items-center'>
                  <p className='view-title' onClick={showAttachFiles}>
                    View Attachments{' '}
                    {showFiles ? (
                      <UpOutlined className='ml-4' />
                    ) : (
                      <DownOutlined className='ml-4' />
                    )}
                  </p>

                  <BrandUploadDocumentModal
                    src={paperclip}
                    creative={creative}
                  />
                </div>
                {showFiles ? (
                  <AttachmentFileCard />
                ) : (
                  <CommentBox creativeId={creative.id} />
                )}
              </div>
            </div>
          </div>
        </div>
      </Modal>
    </>
  );
};

export default CreativeModal;
